head.script:
scwin.trigger1_onclick = function(e) {
    grid1.setCellData(1, 1, "test data!!!");
};
scwin.trigger2_onclick = function(e) {
    grid1.setCellChecked(1, 0, true);
};
scwin.trigger3_onclick = function(e) {
    grid1.setCellReadOnly(3, 0, true);
    grid1.setCellReadOnly(5, 0, true);
    grid1.setCellReadOnly(6, 0, true);
    grid1.setCellData(8, 0, "true");
    grid1.setCellReadOnly(8, 0, true);
    //			grid1.setCellDisabled( 3 , 0 , true );
    //			grid1.setCellDisabled( 5 , 0 , true );
    //			grid1.setCellDisabled( 6 , 0 , true );
    //			grid1.setCellDisabled( 8 , 0 , true );
};
scwin.trigger4_onclick = function(e) {
    grid1.spanAll(true);
};
scwin.trigger5_onclick = function(e) {
    grid1.toggle(0);
};
scwin.trigger6_onclick = function(e) {
    grid1.toggle(6);
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 'toggle(0)'버튼을 클릭한다.
    //1. After executing the sample, click the 'toggle (0)' button.
    //Verify step 1. The 0th index is collapsed. (+1111)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid1_cell_0_1').getElementsByTagName('span')[0].getAttribute('class') == 'w2grid_plus w2grid_root'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'toggle(6)'버튼을 클릭한다.
    //2. Click the 'toggle (6)' button.
    //Verify step 2. The sixth index is collapsed. (+7777)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger6').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid1_cell_1_1').getElementsByTagName('span')[0].getAttribute('class') == 'w2grid_plus w2grid_root'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
